fn frame(t: i32) {
    host::display::clear(0x0a0a12);
    if host::display::state_get(0) == 0 {
        host::display::state_set(1, host::net::open("wss://relay.example.net/lamp"));
        host::display::state_set(0, 1);
    }
    let h: i32 = host::display::state_get(1);
    let mut s: i32 = -1;
    if h >= 0 {
        s = host::net::status(h);
    }
    let mut col: i32 = 0x555555;
    if s == 0 {
        col = 0xaa7700;
    } else if s == 1 {
        col = 0x22bb44;
    } else if s == 2 {
        col = 0xbb7722;
    } else if s == 3 {
        col = 0xbb2222;
    }
    host::display::draw_string(130, 60, "SOCKET STATUS", 0xffffff, 2);
    host::display::fill_rect(216, 140, 80, 80, col);
    if h < 0 {
        host::display::draw_string(190, 260, "OFFLINE", 0xbb2222, 2);
        host::display::draw_string(112, 300, "OPEN REFUSED THE URL POINTER", 0x777777, 1);
    } else if s == 0 {
        host::display::draw_string(160, 260, "CONNECTING", 0xaa7700, 2);
    } else if s == 1 {
        host::display::draw_string(208, 260, "OPEN", 0x22bb44, 2);
    } else if s == 2 {
        host::display::draw_string(184, 260, "CLOSING", 0xbb7722, 2);
    } else {
        host::display::draw_string(190, 260, "CLOSED", 0xbb2222, 2);
    }
    host::display::draw_string(200, 340, "HANDLE", 0x888888, 1);
    host::display::draw_number(248, 338, h, 0xffffff, 1);
    host::display::present();
}
